let raw = '';
if (typeof $json.content === 'string') {
  raw = $json.content;
} else if (Array.isArray($json.content) && $json.content[0] && $json.content[0].text) {
  raw = $json.content[0].text;
} else if (typeof $json.text === 'string') {
  raw = $json.text;
} else if (typeof $json.message === 'string') {
  raw = $json.message;
} else {
  raw = JSON.stringify($json);
}

let result;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  if (!match) throw new Error('no JSON block found in AI response');
  result = JSON.parse(match[0]);
  if (!result.classification) throw new Error('missing classification field');
} catch (e) {
  result = { classification: 'cold', confidence: 0, reasoning: 'parse_error: ' + e.message, draft_reply: '', error: true };
}

const allowedLevel = ['high', 'medium', 'low'];
const normLevel = (v, fallback) => (allowedLevel.includes(v) ? v : fallback);

return {
  json: {
    classification: result.classification,
    confidence: typeof result.confidence === 'number' ? result.confidence : 0,
    reasoning: result.reasoning || '',
    draft_reply: result.draft_reply || '',
    error: result.error === true,
    intent: normLevel(result.intent, 'low'),
    problem_clarity: normLevel(result.problem_clarity, 'low'),
    urgency: normLevel(result.urgency, 'low')
  }
};

