const body = $json.body || {};
let name, email, phone, message, source, chatId, fbMessageId, fbCommentId;

if (Array.isArray(body.field_data) && body.leadgen_id) {
  // Facebook Lead Ads
  const get = (key) => {
    const entry = body.field_data.find(f => f.name === key);
    return entry && Array.isArray(entry.values) ? entry.values[0] : undefined;
  };
  name = get('full_name') || get('name');
  email = get('email');
  phone = get('phone_number') || get('phone');
  message = get('message') || 'Lead submitted via Facebook Lead Ads form (no free-text field provided)';
  source = 'facebook';
} else if (body.event === 'invitee.created' && body.payload) {
  // Calendly
  const p = body.payload;
  name = p.name;
  email = p.email;
  phone = p.text_reminder_number || null;
  if (Array.isArray(p.questions_and_answers) && p.questions_and_answers.length) {
    message = p.questions_and_answers.map(qa => `${qa.question}: ${qa.answer}`).join(' | ');
  } else {
    message = 'Booked a call via Calendly';
  }
  source = 'calendly';
} else if (Array.isArray(body.line_items) && (body.customer || body.email)) {
  // Shopify
  const c = body.customer || {};
  name = [c.first_name, c.last_name].filter(Boolean).join(' ').trim() || undefined;
  email = c.email || body.email;
  phone = c.phone || body.phone;
  message = body.note || `Shopify order/checkout event — ${body.line_items.length} item(s)`;
  source = 'shopify';
} else if (body.event_type === 'form_response' && body.form_response) {
  // Typeform
  const answers = Array.isArray(body.form_response.answers) ? body.form_response.answers : [];
  const getByFieldType = (type) => answers.find(a => a.field && a.field.type === type);
  const nameAns = getByFieldType('short_text');
  const emailAns = getByFieldType('email');
  const phoneAns = getByFieldType('phone_number');
  const messageAns = getByFieldType('long_text');
  name = nameAns ? nameAns.text : undefined;
  email = emailAns ? emailAns.email : undefined;
  phone = phoneAns ? phoneAns.phone_number : undefined;
  message = messageAns ? messageAns.text : undefined;
  source = 'typeform';
} else if (body.update_id !== undefined && body.message) {
  // Telegram
  const m = body.message;
  const from = m.from || {};
  name = [from.first_name, from.last_name].filter(Boolean).join(' ').trim() || undefined;
  email = undefined;
  phone = (m.contact && m.contact.phone_number) || ('telegram:' + (m.chat && m.chat.id));
  message = m.text;
  source = 'telegram';
  chatId = m.chat && m.chat.id;
} else if (typeof body.event_name === 'string' && body.event_name.startsWith('user_send_') && body.sender) {
  // Zalo OA
  name = 'Zalo User ' + body.sender.id;
  email = undefined;
  phone = 'zalo:' + body.sender.id;
  message = body.message && body.message.text;
  source = 'zalo';
} else if (body.object === 'whatsapp_business_account' && Array.isArray(body.entry)) {
  // WhatsApp Business Cloud API
  const value = body.entry[0] && body.entry[0].changes && body.entry[0].changes[0] && body.entry[0].changes[0].value;
  const contact = value && Array.isArray(value.contacts) ? value.contacts[0] : undefined;
  const msg = value && Array.isArray(value.messages) ? value.messages[0] : undefined;
  name = contact && contact.profile ? contact.profile.name : undefined;
  email = undefined;
  phone = msg ? msg.from : undefined;
  message = msg && msg.text ? msg.text.body : undefined;
  source = 'whatsapp';
} else if (body.eventType === 'FORM_RESPONSE' && body.data && Array.isArray(body.data.fields)) {
  // Tally Forms
  const fields = body.data.fields;
  const getByType = (type) => fields.find(f => f.type === type);
  const nameField = getByType('INPUT_TEXT');
  const emailField = getByType('INPUT_EMAIL');
  const phoneField = getByType('INPUT_PHONE_NUMBER');
  const messageField = getByType('TEXTAREA');
  name = nameField ? nameField.value : undefined;
  email = emailField ? emailField.value : undefined;
  phone = phoneField ? phoneField.value : undefined;
  message = messageField ? messageField.value : undefined;
  source = 'tally';
} else if (body.object === 'page' && Array.isArray(body.entry) && body.entry[0] && Array.isArray(body.entry[0].messaging)) {
  // Facebook Messenger
  const msg = body.entry[0].messaging[0];
  const senderId = msg.sender && msg.sender.id;
  name = senderId ? ('Facebook User ' + senderId) : undefined;
  email = undefined;
  phone = senderId ? ('messenger:' + senderId) : undefined;
  message = msg.message && msg.message.text;
  source = 'facebook_messenger';
  fbMessageId = msg.message && msg.message.mid;
} else if (body.object === 'page' && Array.isArray(body.entry) && body.entry[0] && Array.isArray(body.entry[0].changes) && body.entry[0].changes[0] && body.entry[0].changes[0].field === 'feed') {
  // Facebook Page feed event. The `feed` field fires for EVERY activity on a post (status, photo, like, share...), not only comments,
  // so only new comments are treated as leads. The real comment payload does not include the comment `message`: the text is fetched
  // separately through the Graph API by comment_id (see the "Fetch FB Comment Text" and "Merge FB Comment Message" nodes after this one).
  const value = body.entry[0].changes[0].value || {};
  if (value.item !== 'comment' || value.verb !== 'add') {
    // Not a new comment (status/photo/like/share/edit/delete...): ignore, not a lead
    name = undefined; email = undefined; phone = undefined; message = undefined;
    source = 'facebook_comment_ignore';
  } else {
    name = value.from && value.from.name;
    email = undefined;
    phone = undefined;
    message = undefined;
    source = 'facebook_comment';
    fbCommentId = value.comment_id;
  }
} else if (body.object === 'page' && Array.isArray(body.entry) && body.entry[0] && Array.isArray(body.entry[0].changes) && body.entry[0].changes[0] && body.entry[0].changes[0].field === 'ratings') {
  // Facebook Page ratings/reviews. The 'ratings' field fires for many kinds of events (a new rating, a comment or reaction on an existing
  // rating), so filter by whether there is text content, as for comments.
  const value = body.entry[0].changes[0].value || {};
  const content = (typeof value.review_text === 'string' && value.review_text) ||
                  (typeof value.message === 'string' && value.message) || null;
  if (!content) {
    // Reaction-only or rating without text: not enough signal to be a lead
    name = undefined; email = undefined; phone = undefined; message = undefined;
    source = 'facebook_rating_ignore';
  } else {
    const phoneMatch = content.match(/(0|\+84)\d{9,10}/);
    const stars = value.rating ? (value.rating + '/5 sao') : (value.recommendation_type || 'n/a');
    name = value.reviewer_name;
    email = undefined;
    phone = phoneMatch ? phoneMatch[0] : undefined;
    message = '[Rating: ' + stars + '] ' + content;
    source = 'facebook_rating';
  }
} else {
  // Fallback: flat/baseline shape, passthrough unchanged (also covers Google Forms via Apps Script relay)
  name = body.name;
  email = body.email;
  phone = body.phone;
  message = body.message;
  source = body.source;
}

return {
  json: {
    ...$json,
    body: { name, email, phone, message, source, chatId },
    _fbMessageId: fbMessageId,
    _fbCommentId: fbCommentId
  }
};

const headers = $json.headers || {};
const body = $json.body || {};

function simpleHash(str) {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = (h1 ^ (h1 >>> 16)) >>> 0;
  h2 = (h2 ^ (h2 >>> 16)) >>> 0;
  return h1.toString(16) + h2.toString(16);
}

let dedupKey = headers['x-shopify-webhook-id']
  || body.event_id
  || (body.payload && body.payload.uri)
  || (body.entry && body.entry[0] && body.entry[0].messaging && body.entry[0].messaging[0] && body.entry[0].messaging[0].message && body.entry[0].messaging[0].message.mid)
  || (body.entry && body.entry[0] && body.entry[0].changes && body.entry[0].changes[0] && body.entry[0].changes[0].value && body.entry[0].changes[0].value.comment_id)
  || null;

// Facebook ratings: open_graph_story_id alone is not enough, because Facebook resends the event (add/edit) even when the review text is
// identical OR when the customer really edited it. Combine it with a hash of the review text: same ID + same text -> duplicate (a retry);
// same ID + different text (an edited review) -> NOT a duplicate, treated as a new lead.
const ratingValue = body.entry && body.entry[0] && body.entry[0].changes && body.entry[0].changes[0] && body.entry[0].changes[0].value;
const ogsid = ratingValue && ratingValue.open_graph_story_id;
if (ogsid) {
  const reviewContent = (typeof ratingValue.review_text === 'string' && ratingValue.review_text) ||
                        (typeof ratingValue.message === 'string' && ratingValue.message) || '';
  dedupKey = ogsid + ':' + simpleHash(reviewContent);
}

dedupKey = dedupKey
  || body.eventId
  || body.update_id
  || (body.entry && body.entry[0] && body.entry[0].changes && body.entry[0].changes[0] && body.entry[0].changes[0].value && Array.isArray(body.entry[0].changes[0].value.messages) && body.entry[0].changes[0].value.messages[0] && body.entry[0].changes[0].value.messages[0].id)
  || (body.message && body.message.msg_id)
  || body.google_forms_id
  || null;

if (!dedupKey) {
  dedupKey = 'hash:' + simpleHash(JSON.stringify(body));
}

return {
  json: {
    ...$json,
    _dedupKey: dedupKey,
  }
};

const body = $json.body || {};
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const chatSources = ['telegram', 'zalo', 'whatsapp', 'facebook_messenger', 'facebook_comment', 'facebook_rating'];

const hasValidEmail = typeof body.email === 'string' && emailRegex.test(body.email);
const hasValidPhoneForChat = chatSources.includes(body.source) && typeof body.phone === 'string' && body.phone.trim() !== '';

return {
  json: {
    ...$json,
    hasValidContact: hasValidEmail || hasValidPhoneForChat,
  }
};

