const cfg = $('Scoring Config').item.json.scoringConfig.weights.fit;
const body = $json.body || {};
const chatSources = ['telegram', 'zalo', 'whatsapp', 'facebook_messenger', 'facebook_comment', 'facebook_rating'];
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

let score = 0;
const positive = [];
const negative = [];

if (typeof body.source === 'string' && body.source.trim() !== '') {
  score += cfg.sourceValid;
  positive.push('Source is clearly identified');
} else {
  negative.push('Lead source could not be determined');
}

const hasEmail = typeof body.email === 'string' && emailRegex.test(body.email);
const hasPhone = typeof body.phone === 'string' && body.phone.trim() !== '';
const isChatSource = chatSources.includes(body.source);

// Contact completeness: SAME max points (cfg.contactComplete) regardless of source
// type, to avoid a bias between chat sources and form sources.
// Chat sources never collect a real email by design, so judge them on phone/fallback
// identifier alone; form sources need BOTH email and phone for full credit.
if (isChatSource) {
  if (hasPhone) {
    score += cfg.contactComplete;
    positive.push('Has phone number or contact identifier (sufficient for chat-based source)');
  } else {
    negative.push('No phone number or contact identifier');
  }
} else {
  if (hasEmail && hasPhone) {
    score += cfg.contactComplete;
    positive.push('Has both email and phone number');
  } else if (hasEmail || hasPhone) {
    score += cfg.contactComplete / 2;
    positive.push(hasEmail ? 'Has valid email (missing phone number)' : 'Has phone number (missing email)');
  } else {
    negative.push('Missing both email and phone number');
  }
}

return {
  json: {
    ...$json,
    fitScore: score,
    fitScoreReason: { positive, negative }
  }
};

const cfg = $('Scoring Config').item.json.scoringConfig.weights.intent;
const j = $json;

let score = 0;
const positive = [];
const negative = [];

if (j.intent === 'high') {
  score += cfg.intentHigh;
  positive.push('AI assessed buying intent as high');
} else if (j.intent === 'medium') {
  score += cfg.intentMedium;
  positive.push('AI assessed buying intent as medium');
} else {
  negative.push('AI assessed buying intent as low/unclear');
}

if (j.problem_clarity === 'high') {
  score += cfg.problemClarityHigh;
  positive.push('Problem/need is clearly described');
} else if (j.problem_clarity === 'medium') {
  score += cfg.problemClarityMedium;
} else {
  negative.push('Problem/need is not clearly described');
}

if (j.urgency === 'high') {
  score += cfg.urgencyHigh;
  positive.push('Shows high urgency signal (needs action soon)');
} else if (j.urgency === 'medium') {
  score += cfg.urgencyMedium;
}

return {
  json: {
    ...$json,
    intentScore: score,
    intentScoreReason: { positive, negative }
  }
};

const cfg = $('Scoring Config').item.json.scoringConfig;
const fit = $('Compute Fit Score').item.json;
const j = $json;

const fitScore = fit.fitScore;
const intentScore = j.intentScore;
const leadScore = fitScore + intentScore;

let leadGrade = 'cold';
if (leadScore >= cfg.thresholds.hot) leadGrade = 'hot';
else if (leadScore >= cfg.thresholds.warm) leadGrade = 'warm';

const positive = [...(fit.fitScoreReason ? fit.fitScoreReason.positive : []), ...(j.intentScoreReason ? j.intentScoreReason.positive : [])];
const negative = [...(fit.fitScoreReason ? fit.fitScoreReason.negative : []), ...(j.intentScoreReason ? j.intentScoreReason.negative : [])];

return {
  json: {
    ...j,
    fitScore,
    intentScore,
    leadScore,
    leadGrade,
    scoreReason: { positive, negative },
    scoreVersion: cfg.score_version,
    legacyClassification: j.classification
  }
};

// Resolve Customer Identity: identity resolution + auto-merge.
// Matching key: email OR phone (normalized), never chat fallback identifiers
// (those contain ':', e.g. "telegram:12345" - only meaningful within their own channel).
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const fl = $('Format Lead').item.json;
const rawEmail = fl.Email;
const rawPhone = fl.Phone;

const normEmail = (typeof rawEmail === 'string' && emailRegex.test(rawEmail)) ? rawEmail.trim().toLowerCase() : null;
const normPhone = (typeof rawPhone === 'string' && !rawPhone.includes(':') && rawPhone.trim() !== '')
  ? rawPhone.replace(/[^0-9]/g, '')
  : null;

const baseUrl = 'https://api.airtable.com/v0/' + $env.AIRTABLE_BASE_ID;
const authHeader = { Authorization: 'Bearer ' + $env.AIRTABLE_API_KEY };
const customersTable = 'Customers';
const nowIso = new Date().toISOString();

let matches = [];
if (normEmail || normPhone) {
  const filters = [];
  if (normEmail) filters.push(`{Primary Email}='${normEmail}'`);
  if (normPhone) filters.push(`{Primary Phone}='${normPhone}'`);
  const formula = filters.length > 1 ? `OR(${filters.join(',')})` : filters[0];
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: baseUrl + '/' + encodeURIComponent(customersTable),
    qs: { filterByFormula: formula },
    headers: authHeader,
    json: true
  });
  matches = res.records || [];
}

let customerId = null;
let mergeInfo = null;

if (matches.length === 0) {
  const createRes = await this.helpers.httpRequest({
    method: 'POST',
    url: baseUrl + '/' + encodeURIComponent(customersTable),
    headers: authHeader,
    json: true,
    body: {
      fields: {
        Name: fl.Name,
        'Primary Email': normEmail || undefined,
        'Primary Phone': normPhone || undefined,
        'First Seen At': nowIso,
        'Last Seen At': nowIso,
        'Total Leads': 1,
        Status: 'active'
      }
    }
  });
  customerId = createRes.id;
} else if (matches.length === 1) {
  const c = matches[0];
  customerId = c.id;
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: baseUrl + '/' + encodeURIComponent(customersTable) + '/' + c.id,
    headers: authHeader,
    json: true,
    body: {
      fields: {
        'Last Seen At': nowIso,
        'Total Leads': (c.fields['Total Leads'] || 0) + 1
      }
    }
  });
} else {
  // Merge conflict: 2+ distinct customers matched by different keys (email vs phone).
  // Merge policy: auto-merge, survivor = earliest First Seen At.
  const sorted = [...matches].sort((a, b) => new Date(a.fields['First Seen At']) - new Date(b.fields['First Seen At']));
  const survivor = sorted[0];
  const losers = sorted.slice(1);
  customerId = survivor.id;

  for (const loser of losers) {
    const loserLeadIds = loser.fields['Leads'] || [];
    for (const leadId of loserLeadIds) {
      await this.helpers.httpRequest({
        method: 'PATCH',
        url: baseUrl + '/' + encodeURIComponent($env.AIRTABLE_TABLE_NAME) + '/' + leadId,
        headers: authHeader,
        json: true,
        body: { fields: { Customer: [survivor.id] } }
      });
    }
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: baseUrl + '/' + encodeURIComponent(customersTable) + '/' + loser.id,
      headers: authHeader,
      json: true,
      body: { fields: { Status: 'merged', 'Merged Into': [survivor.id] } }
    });
  }

  const loserLeadCount = losers.reduce((sum, l) => sum + (l.fields['Total Leads'] || 0), 0);
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: baseUrl + '/' + encodeURIComponent(customersTable) + '/' + survivor.id,
    headers: authHeader,
    json: true,
    body: {
      fields: {
        'Last Seen At': nowIso,
        'Total Leads': (survivor.fields['Total Leads'] || 0) + 1 + loserLeadCount
      }
    }
  });

  mergeInfo = { survivorId: survivor.id, loserIds: losers.map(l => l.id) };
}

return {
  json: {
    ...$json,
    customerId,
    customerMergeInfo: mergeInfo
  }
};

// Extract a phone number the customer typed in the message text, for ALL sources (generalizes the regex used for Facebook comments in
// "Merge FB Comment Message"). It does not touch body.phone: purely additive, so validation and dedup behave as before.
const body = $json.body || {};
const text = typeof body.message === 'string' ? body.message : '';
const match = text.match(/(0|\+84)\d{9,10}/);

return {
  json: {
    ...$json,
    messagePhone: match ? match[0] : null
  }
};

// Warm lead outreach readiness: multi-channel, the channels are not mutually exclusive.
const fl = $('Format Lead').item.json;
const messagePhone = $('Extract Phone From Message').item.json.messagePhone;
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const source = fl.Source;
const phone = fl.Phone;
const email = fl.Email;

const channels = [];
let emailIdentifier = null;
let chatIdentifier = null;

if (typeof email === 'string' && emailRegex.test(email)) {
  channels.push('email');
  emailIdentifier = email;
}

const isPrefixed = typeof phone === 'string' && phone.includes(':');
const realPlatformPhone = (typeof phone === 'string' && !isPrefixed && phone.trim() !== '') ? phone : null;

if (messagePhone || realPlatformPhone) {
  channels.push('phone');
}

if (source === 'telegram') {
  channels.push('telegram');
  chatIdentifier = typeof phone === 'string' ? phone.replace('telegram:', '') : null;
} else if (source === 'whatsapp') {
  channels.push('whatsapp');
  chatIdentifier = phone;
} else if (source === 'zalo') {
  channels.push('zalo');
  chatIdentifier = typeof phone === 'string' ? phone.replace('zalo:', '') : null;
} else if (source === 'facebook_messenger') {
  channels.push('facebook_messenger');
  chatIdentifier = typeof phone === 'string' ? phone.replace('messenger:', '') : null;
}

if (channels.length === 0) {
  channels.push('none');
}

// Priority: phone typed by the customer in the message > email > identifier of a dedicated chat channel > real platform phone
let outreachIdentifier = null;
if (messagePhone) outreachIdentifier = messagePhone;
else if (emailIdentifier) outreachIdentifier = emailIdentifier;
else if (chatIdentifier) outreachIdentifier = chatIdentifier;
else if (realPlatformPhone) outreachIdentifier = realPlatformPhone;

return {
  json: {
    ...$json,
    outreachChannels: channels,
    outreachIdentifier,
    messagePhone: messagePhone || null
  }
};

// n8n's built-in Redis "get" node does not keep the original data (it only returns the field named by propertyName):
// restore body/_dedupKey from the earlier node and attach the Redis result to the same item.
const original = $('Check Duplicate Webhook').item.json;
return {
  json: {
    ...original,
    dedupExisting: $json.dedupExisting
  }
};

// Redis AI classification cache: hash of the content (name + message + source). Uses the same manual hash pattern as
// Check Duplicate Webhook, so it does not depend on the n8n sandbox allowing the crypto module.
function simpleHash(str) {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = (h1 ^ (h1 >>> 16)) >>> 0;
  h2 = (h2 ^ (h2 >>> 16)) >>> 0;
  return h1.toString(16) + h2.toString(16);
}

const body = $json.body || {};
const keyInput = (body.name || '') + '|' + (body.message || '') + '|' + (body.source || '');

return {
  json: {
    ...$json,
    contentHash: simpleHash(keyInput)
  }
};

// n8n's built-in Redis "get" node does not keep the original data: restore it (same cause as the dedup merge node).
const original = $('Compute Content Hash').item.json;
return {
  json: {
    ...original,
    cachedResult: $json.cachedResult
  }
};

let result;
try {
  result = JSON.parse($json.cachedResult);
} catch (e) {
  result = { classification: 'cold', confidence: 0, reasoning: 'cache_parse_error: ' + e.message, draft_reply: '', error: true, intent: 'low', problem_clarity: 'low', urgency: 'low' };
}
return { json: result };

// Prepare the raw payload for archiving in MongoDB. Runs FIRST in the pipeline, before dedup and normalize, so no request is missed
// (including requests that will be rejected with 400 after validation).
const headers = $json.headers || {};
const body = $json.body || {};

let sourceGuess = 'unknown';
if (headers['x-shopify-webhook-id']) sourceGuess = 'shopify';
else if (body.event_type === 'form_response') sourceGuess = 'typeform';
else if (body.update_id !== undefined) sourceGuess = 'telegram';
else if (typeof body.event_name === 'string' && body.event_name.startsWith('user_send_')) sourceGuess = 'zalo';
else if (body.object === 'whatsapp_business_account') sourceGuess = 'whatsapp';
else if (body.object === 'page') sourceGuess = 'facebook_page_event';
else if (body.eventType === 'FORM_RESPONSE') sourceGuess = 'tally';
else if (body.event === 'invitee.created') sourceGuess = 'calendly';
else if (Array.isArray(body.line_items)) sourceGuess = 'shopify';
else if (body.google_forms_id) sourceGuess = 'google_forms';
else if (Array.isArray(body.field_data)) sourceGuess = 'facebook_lead_ads';
else if (typeof body.source === 'string' && body.source.trim() !== '') sourceGuess = body.source;

return {
  json: {
    ...$json,
    rawHeaders: headers,
    rawBody: body,
    sourceGuess,
    archivedAt: new Date().toISOString(),
    webhookPath: 'lead-intake'
  }
};
